<style>
  :root{
    --navy:#0B3B39;
    --navy-deep:#062422;
    --sand:#F6EFE1;
    --card:#FFFFFF;
    --coral:#E2632F;
    --gold:#C79A4B;
    --ink:#1C2B29;
    --ink-soft:#5C6D6A;
    --line:#E4DAC5;
    --radius:16px;
  }
  *{box-sizing:border-box;margin:0;padding:0;}
  html{scroll-behavior:smooth;overflow-x:hidden;background:var(--sand);}
  body{overflow-x:hidden;}
  body{
    background:var(--sand);color:var(--ink);
    font-family:'IBM Plex Sans Arabic', sans-serif;
    line-height:1.7;-webkit-font-smoothing:antialiased;
    padding-bottom:70px;
  }
  body.lang-en{font-family:'Poppins', sans-serif;}
  h1,h2,h3,.display{font-family:'Changa', sans-serif;font-weight:800;}
  body.lang-en h1, body.lang-en h2, body.lang-en h3, body.lang-en .display{font-family:'Poppins', sans-serif;font-weight:700;}
  a{color:inherit;text-decoration:none;}
  img{max-width:100%;display:block;}
  .wrap{max-width:1080px;margin:0 auto;padding:0 20px;}
  button{font-family:inherit;cursor:pointer;}

  header{
    position:sticky;top:0;z-index:60;
    background:rgba(246,239,225,0.92);backdrop-filter:blur(10px);
    border-bottom:1px solid var(--line);
  }
  .nav{display:flex;align-items:center;justify-content:space-between;padding:14px 0;gap:10px;}
  .logo{font-size:21px;display:flex;align-items:center;gap:8px;color:var(--navy);}
  .logo small{font-family:'IBM Plex Sans Arabic';font-weight:400;font-size:11px;color:var(--ink-soft);display:block;}
  body.lang-en .logo small{font-family:'Poppins';}
  .logo-mark{height:28px;width:28px;max-width:28px;object-fit:contain;display:block;flex:0 0 28px;}
  .nav-right{display:flex;align-items:center;gap:10px;}
  .lang-btn{
    background:#fff;border:1.5px solid var(--line);color:var(--navy);
    border-radius:999px;padding:8px 14px;font-size:13px;font-weight:700;
  }
  .lang-btn:hover{border-color:var(--navy);}
  .cart-btn{
    position:relative;background:var(--navy);color:#fff;border:none;
    width:46px;height:46px;border-radius:50%;font-size:19px;
    display:flex;align-items:center;justify-content:center;flex:0 0 auto;
  }
  .cart-btn .count{
    position:absolute;top:-4px;left:-4px;background:var(--coral);color:#fff;
    font-size:11px;font-weight:700;width:20px;height:20px;border-radius:50%;
    display:flex;align-items:center;justify-content:center;
  }

  .hero{
    position:relative;background:linear-gradient(160deg,var(--navy) 0%, var(--navy-deep) 100%);
    color:#fff;padding:44px 0 80px;overflow:hidden;
  }
  .hero .bubbles{position:absolute;inset:0;opacity:.15;pointer-events:none;
    background-image:radial-gradient(circle, #fff 2px, transparent 2px);
    background-size:46px 46px;
  }
  .hero-inner{position:relative;text-align:center;}
  .hero-logo{display:block;width:150px;max-width:72vw;height:auto;max-height:150px;object-fit:contain;object-position:center;margin:0 auto 16px;filter:drop-shadow(0 6px 16px rgba(0,0,0,.25));}
  .menu-grid img,.item-card img{max-width:100%;height:auto;object-fit:contain;object-position:center;}

  .branch-badge{
    display:inline-block;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.25);
    color:#fff;font-size:12.5px;font-weight:600;padding:6px 16px;border-radius:999px;
    margin-bottom:10px;letter-spacing:.3px;cursor:pointer;
  }
  .branch-badge:empty{display:none}
  .branch-strip{background:#fff;border-bottom:1px solid var(--line);position:sticky;top:63px;z-index:55;}
  .branch-strip .wrap{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:9px 20px;flex-wrap:wrap;}
  .branch-strip-btn{background:var(--navy);color:#fff;border:none;border-radius:999px;padding:9px 18px;font-size:13px;font-weight:800;display:flex;align-items:center;gap:6px;}
  .branch-strip-sub{font-size:11.5px;color:var(--ink-soft);font-weight:500;}
  .branch-modal-overlay{position:fixed;inset:0;background:rgba(6,36,34,.55);z-index:200;display:none;align-items:flex-end;justify-content:center;backdrop-filter:blur(2px);}
  .branch-modal-overlay.open{display:flex;}
  .branch-modal{background:#fff;width:100%;max-width:480px;border-radius:22px 22px 0 0;padding:22px 18px 26px;max-height:88vh;overflow-y:auto;box-shadow:0 -10px 40px rgba(0,0,0,.25);}
  .branch-welcome{margin:22px auto 0;max-width:390px;padding:18px 18px 20px;background:rgba(255,255,255,.11);border:1px solid rgba(255,255,255,.22);border-radius:22px;backdrop-filter:blur(8px);box-shadow:0 14px 35px rgba(0,0,0,.16);}
  .branch-welcome-icon{font-size:30px;margin-bottom:5px}.branch-welcome-title{font-size:21px;font-weight:900;margin-bottom:5px}.branch-welcome-text{font-size:12.5px;color:#d7ebe8;line-height:1.7;margin-bottom:13px}.branch-welcome-btn{border:0;background:#fff;color:var(--navy);border-radius:999px;padding:11px 20px;font-weight:900;font-size:14px;cursor:pointer;box-shadow:0 8px 22px rgba(0,0,0,.16)}.branch-welcome-btn span{display:inline-block;margin-right:8px;font-size:17px}
  .item-price-tag{display:inline-flex;align-items:center;gap:5px;margin-top:7px;padding:5px 9px;border-radius:999px;background:#f0f8f6;border:1px solid #d6e9e5;color:var(--navy);font-size:12px;font-weight:900}.item-price-tag.weight-price{background:#fff8e8;border-color:#f4dfaa;color:#805b00}
  .cart-row-price strong{color:var(--navy);}

  @media(min-width:560px){.branch-modal-overlay{align-items:center;}.branch-modal{border-radius:22px;}}
  .branch-chooser-title{font-weight:900;color:var(--navy);margin-bottom:14px;font-size:17px;}
  .branch-chooser-title span{display:block;font-size:12px;font-weight:500;color:var(--ink-soft);margin-top:4px;}
  .branch-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px;}
  .branch-option{border:1.5px solid var(--line);background:#fff;border-radius:14px;padding:13px 12px;display:flex;justify-content:space-between;align-items:center;color:var(--navy);font-weight:800;cursor:pointer;font-size:13.5px;transition:.15s;}
  .branch-option:hover{border-color:var(--navy);}
  .branch-option.selected{border-color:var(--coral);background:#fdf1ec;box-shadow:0 0 0 2px rgba(226,99,47,.15);}
  .branch-option.closed{opacity:.5;cursor:not-allowed;background:#f7f7f7;}
  .branch-option.closed small{color:#d92d20;font-weight:700;}
  .branch-locate-btn{width:100%;background:#f3faf8;border:1.5px dashed #0f766e;color:#0f766e;border-radius:12px;padding:11px;font-weight:800;font-size:13px;margin-bottom:12px;}
  .branch-check{color:var(--coral);font-size:17px;}
  .chosen-branch-line{margin-top:14px;padding:10px 12px;border-radius:12px;background:#ecfdf8;color:#0f766e;font-size:12.5px;font-weight:700;}
  .branch-modal-close{margin-top:16px;width:100%;background:none;border:1.5px solid var(--line);border-radius:12px;padding:11px;font-weight:800;color:var(--ink-soft);}
  .checkout-branch-line{display:flex;align-items:center;justify-content:space-between;background:#f3faf8;border:1px solid #d8e6e3;border-radius:12px;padding:12px 14px;font-weight:800;color:#123b39;margin-bottom:4px;}
  .checkout-branch-line .branch-change-link{background:none;border:none;color:var(--coral);font-weight:800;font-size:12.5px;text-decoration:underline;padding:0;}
  .receipt-upload-box{border:1.5px dashed #0f766e;background:#f3faf8;border-radius:14px;padding:14px;margin-top:12px;color:#123b39;}
  .receipt-upload-box input[type="file"]{width:100%;box-sizing:border-box;padding:8px;border:1px solid #d8e6e3;border-radius:10px;background:#fff;font-size:12.5px;}
  .order-progress{display:flex;justify-content:space-between;margin:16px 0;position:relative;}
  .order-progress::before{content:'';position:absolute;top:13px;left:6%;right:6%;height:3px;background:#e7efec;z-index:0;}
  .order-progress .step{position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;gap:5px;flex:1;}
  .order-progress .dot{width:26px;height:26px;border-radius:50%;background:#e7efec;color:#9fb0aa;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:800;}
  .order-progress .step.done .dot{background:#0f766e;color:#fff;}
  .order-progress .step.current .dot{background:var(--coral);color:#fff;box-shadow:0 0 0 4px rgba(226,99,47,.18);}
  .order-progress .label{font-size:9.5px;color:#7a8b86;text-align:center;max-width:60px;}
  .order-progress .step.done .label, .order-progress .step.current .label{color:#123b39;font-weight:800;}
  .discount-badge{
    display:inline-block;background:var(--coral);color:#fff;
    font-size:13px;font-weight:700;padding:7px 18px;border-radius:999px;
    margin-bottom:14px;letter-spacing:.2px;
  }
  .hero .eyebrow{
    display:inline-flex;align-items:center;gap:8px;color:var(--gold);
    font-size:13px;font-weight:600;letter-spacing:.5px;margin-bottom:12px;
  }
  .hero h1{font-size:clamp(26px,5.5vw,40px);margin-bottom:10px;}
  .hero p{color:#CFE3E0;font-size:14px;max-width:420px;margin:0 auto 8px;}
  .price-note{color:#9FC2BE;font-size:12px;margin-bottom:20px;}
  .discount-badge{
    display:inline-flex;align-items:center;gap:8px;background:var(--coral);
    color:#fff;font-weight:700;font-size:13.5px;padding:9px 20px;border-radius:999px;
    margin-bottom:18px;box-shadow:0 8px 20px rgba(226,99,47,.35);
  }
  .wave{position:absolute;bottom:-1px;left:0;width:100%;line-height:0;}

  .search-bar{
    max-width:1080px;margin:-46px auto 0;padding:0 20px;position:relative;z-index:10;
  }
  .search-bar input{
    width:100%;padding:14px 18px;border-radius:999px;border:1px solid var(--line);
    background:#fff;font-size:14px;box-shadow:0 10px 30px rgba(6,36,34,.12);
    font-family:inherit;color:var(--ink);
  }
  .search-bar input:focus{outline:2px solid var(--coral);}

  .cats{
    display:flex;gap:10px;overflow-x:auto;padding:22px 20px 6px;
    max-width:1080px;margin:0 auto;
  }
  .cats::-webkit-scrollbar{display:none;}
  .cat-btn{
    flex:0 0 auto;padding:10px 20px;border-radius:999px;border:1.5px solid var(--line);
    background:#fff;font-size:14px;font-weight:600;color:var(--ink-soft);white-space:nowrap;
  }
  .cat-btn.active{background:var(--navy);color:#fff;border-color:var(--navy);}

  .menu-section{padding:10px 0 40px;}
  .menu-cat-title{font-size:20px;margin:26px 20px 4px;color:var(--navy);display:flex;align-items:center;gap:8px;}
  .menu-cat-note{font-size:12px;color:var(--ink-soft);margin:0 20px 14px;}
  .menu-grid{
    display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));
    gap:16px;padding:0 20px;
  }
  .item-card{
    background:var(--card);border:1px solid var(--line);border-radius:var(--radius);
    padding:14px;display:flex;gap:14px;align-items:center;
  }
  .item-thumb{
    width:52px;height:52px;border-radius:12px;flex:0 0 52px;
    background:linear-gradient(150deg,var(--gold),var(--coral));
    display:flex;align-items:center;justify-content:center;font-size:22px;color:#fff;
  }
  .item-info{flex:1;min-width:0;}
  .item-name{font-weight:700;font-size:15px;margin-bottom:2px;}
  .item-desc{font-size:12px;color:var(--ink-soft);margin-bottom:8px;line-height:1.5;}
  .item-footer{display:flex;align-items:center;justify-content:space-between;}
  .item-price{font-family:'Changa';font-weight:700;color:var(--navy);font-size:15px;}
  body.lang-en .item-price{font-family:'Poppins';}
  .add-btn{
    background:var(--navy);color:#fff;border:none;border-radius:999px;
    width:32px;height:32px;font-size:17px;display:flex;align-items:center;justify-content:center;
  }
  .qty-stepper{display:flex;align-items:center;gap:10px;background:var(--sand);border-radius:999px;padding:4px 8px;}
  .qty-stepper button{background:none;border:none;width:24px;height:24px;font-size:16px;color:var(--navy);font-weight:700;}
  .qty-stepper span{font-weight:700;min-width:16px;text-align:center;}
  .qty-stepper.weight span{min-width:52px;font-size:12.5px;}
  .weight-total{font-size:11.5px;color:var(--coral);font-weight:700;margin-top:4px;}
  .fish-controls{margin-top:8px;display:flex;flex-direction:column;gap:6px;}
  .stepper-row{display:flex;align-items:center;justify-content:space-between;gap:8px;}
  .stepper-label{font-size:11.5px;color:var(--ink-soft);font-weight:600;}
  .note-toggle{
    background:none;border:none;color:var(--ink-soft);font-size:11.5px;
    text-decoration:underline;padding:0;margin-top:6px;display:inline-block;
  }
  .note-input{
    width:100%;margin-top:8px;border:1px solid var(--line);border-radius:10px;
    padding:8px 10px;font-size:12.5px;font-family:inherit;color:var(--ink);
    resize:vertical;min-height:36px;background:var(--sand);
  }
  .note-input:focus{outline:2px solid var(--coral);}
  .no-results{padding:40px 20px;text-align:center;color:var(--ink-soft);}

  .overlay{
    position:fixed;inset:0;background:rgba(6,36,34,.5);z-index:80;
    opacity:0;pointer-events:none;transition:opacity .25s ease;
  }
  .overlay.open{opacity:1;pointer-events:auto;}
  .drawer{
    position:fixed;top:0;left:0;right:auto;height:100%;width:min(400px,90vw);
    background:#fff;z-index:90;transform:translate3d(-105%,0,0);
    transition:transform .3s ease;display:flex;flex-direction:column;
    visibility:hidden;
  }
