  .drawer.checkout-mode .drawer-foot.checkout-scroll{flex:1;}
  .sub-row{display:flex;justify-content:space-between;font-size:13px;color:var(--ink-soft);margin-bottom:6px;}
  .discount-row{display:flex;justify-content:space-between;font-size:13px;color:var(--coral);font-weight:700;margin-bottom:6px;}
  .total-row{display:flex;justify-content:space-between;font-weight:700;font-size:17px;margin-bottom:14px;color:var(--navy);padding-top:8px;border-top:1px dashed var(--line);}
  .checkout-btn{
    width:100%;background:var(--coral);color:#fff;border:none;border-radius:999px;
    padding:15px;font-weight:700;font-size:15px;
  }
  .checkout-btn:disabled{background:#D8CDBB;color:#8c8375;}

  .checkout-note{
    background:var(--sand);border:1px solid var(--line);border-radius:12px;
    padding:12px 14px;font-size:12.5px;color:var(--ink-soft);margin-bottom:14px;line-height:1.6;
  }
  .wa-btn{
