    padding:15px;font-weight:700;font-size:15px;display:flex;align-items:center;justify-content:center;gap:8px;
  }
  .floating-wa{
    position:fixed;bottom:22px;right:22px;z-index:120;display:flex;align-items:center;gap:10px;
    background:#25D366;color:#fff;text-decoration:none;border-radius:999px;padding:12px 18px 12px 14px;
    box-shadow:0 10px 28px rgba(0,0,0,.18);font-weight:800;font-size:13px;
    transition:transform .2s ease, box-shadow .2s ease;
