  html[dir="ltr"] .floating-wa{right:auto;left:22px;padding:12px 14px 12px 18px;}
  @media(max-width:600px){.wrap{padding-left:14px;padding-right:14px}.hero{padding-top:28px}.hero-logo{width:120px;max-width:58vw;max-height:120px}.logo{font-size:18px;min-width:0}.logo small{font-size:9px}.nav{padding:10px 0}.nav-right{gap:6px}.menu-grid{grid-template-columns:1fr;padding-left:14px;padding-right:14px}.item-card{min-width:0}.floating-wa{bottom:16px;right:14px;padding:10px 14px 10px 11px}.floating-wa .wa-icon{width:31px;height:31px}.floating-wa .wa-icon svg{width:20px;height:20px}html[dir="ltr"] .floating-wa{right:auto;left:14px;padding:10px 11px 10px 14px;}}
