  .open-status{display:inline-block;margin-top:10px;padding:5px 12px;border-radius:999px;background:#ffffff1a;font-size:12px}.open-status.closed{background:#7d1f1f;color:#ffd9d9}.review-section{padding:28px 20px 10px}.review-card{max-width:720px;margin:auto;background:#fff;border:1px solid var(--line);border-radius:18px;padding:20px}.stars button{border:0;background:none;font-size:28px;color:#c9bfae;cursor:pointer}.stars button.active{color:#f2b63d}.review-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.review-grid input,.review-card textarea{width:100%;padding:11px;border:1px solid var(--line);border-radius:10px;font:inherit}.review-card textarea{min-height:80px;margin-top:10px}.review-list{display:grid;gap:10px;margin-top:16px}.review-item{background:#faf7ef;border:1px solid var(--line);border-radius:12px;padding:12px}.socials{display:flex;justify-content:center;gap:12px;margin-top:14px}.socials a{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;background:#fff;border:1px solid var(--line)}.socials svg{width:22px;height:22px}.review-success{color:#15803d;margin-top:8px;font-size:13px}footer{padding:34px 0;text-align:center;color:var(--ink-soft);font-size:13px}

  .floating-wa{position:fixed;bottom:20px;right:20px;z-index:80;display:flex;align-items:center;gap:8px;padding:11px 14px;border-radius:999px;background:#20b45a;color:#fff;font-weight:800;box-shadow:0 12px 30px #0003;border:2px solid #fff;text-decoration:none}.floating-wa .wa-icon{width:30px;height:30px;border-radius:50%;background:#fff;color:#20b45a;display:grid;place-items:center;font-size:18px}.floating-wa span{white-space:nowrap}.location-box{border:1px dashed #cfc3ae;background:#fbf8f0;border-radius:14px;padding:12px}.location-btn{width:100%;border:1px solid #cfc3ae;background:#fff;color:var(--navy);border-radius:12px;padding:11px;font-weight:700}.location-status{font-size:12px;color:var(--ink-soft);margin-top:7px}.location-status.ok{color:#15803d}.location-link{display:none;margin-top:7px;font-size:12px;color:#0b67a0;text-decoration:underline}.location-link.show{display:inline-block}.gps-dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:#e2632f;margin-left:5px}.location-help{font-size:11px;color:var(--ink-soft);margin-top:6px}
