.checkout-form{display:flex;flex-direction:column;gap:10px}.checkout-form h3{margin:0 0 6px}.checkout-form input,.checkout-form textarea,.checkout-form select{width:100%;box-sizing:border-box;padding:12px;border:1px solid #ddd;border-radius:12px;font:inherit;background:#fff}.checkout-form textarea{min-height:80px;resize:vertical}.checkout-error{color:#b42318;min-height:20px;font-size:13px}.order-success{text-align:center;padding:20px 8px}.success-icon{width:58px;height:58px;border-radius:50%;display:grid;place-items:center;margin:0 auto 12px;background:#e8f7ed;color:#15803d;font-size:32px;font-weight:700}

