async function loadSiteSettings(){ try{ const r=await fetch('api.php?action=get_public_settings&_='+Date.now(),{cache:'no-store',credentials:'same-origin'}); const d=await r.json(); if(d.ok) window.SG_SETTINGS=Object.assign(window.SG_SETTINGS,d.settings||{}); await refreshBranchMenu(); await loadPublicBranches(); updateOpeningState(); }catch(e){ console.error(e); } }
async function refreshBranchMenu(){ if(!selectedBranch){ MENU_DATA={cats:{},icons:{},items:[]}; renderCats(); renderMenu(); return; } try{ const mr=await fetch('api.php?action=get_public_menu&branch_id='+encodeURIComponent(selectedBranch)+'&_='+Date.now(),{cache:'no-store',credentials:'same-origin'}); const md=await mr.json(); if(md.ok&&md.menu){ MENU_DATA=md.menu; activeCat='ALL'; renderCats(); renderMenu(); } }catch(e){ console.error(e); } }
function updateOpeningState(){ const {open,close}=effectiveHours(); const now=new Date(); const mins=now.getHours()*60+now.getMinutes(); const op=open.split(':').map(Number), cl=close.split(':').map(Number); const om=op[0]*60+op[1], rawcm=cl[0]*60+cl[1], cm=rawcm===0?1440:rawcm; let isOpen=(om<=cm ? mins>=om&&mins<cm : mins>=om||mins<cm); const badge=document.getElementById('openStatus'); if(badge){badge.textContent=isOpen?(lang==='ar'?'🟢 مفتوح الآن':'🟢 Open now'):(lang==='ar'?'🔴 مغلق الآن':'🔴 Closed now'); badge.className='open-status '+(isOpen?'open':'closed');} }
let lang = (function(){try{return localStorage.getItem('sgLang')==='en'?'en':'ar';}catch(e){return 'ar';}})();
let activeCat = 'ALL';
let searchQuery = '';
