async function loadPublicBranches(){ try{ const r=await fetch('api.php?action=list_public_branches&_='+Date.now(),{cache:'no-store',credentials:'same-origin'}); const d=await r.json(); if(d.ok){ BRANCH_INFO={}; (d.branches||[]).forEach(b=>BRANCH_INFO[b.id]=b); if(document.getElementById('branchPicker')?.classList.contains('open'))renderBranchChooser(); updateOpeningState(); } }catch(e){ console.error(e); } }
function haversineKm(lat1,lng1,lat2,lng2){ const R=6371,toRad=d=>d*Math.PI/180; const dLat=toRad(lat2-lat1),dLng=toRad(lng2-lng1); const a=Math.sin(dLat/2)**2+Math.cos(toRad(lat1))*Math.cos(toRad(lat2))*Math.sin(dLng/2)**2; return R*2*Math.asin(Math.sqrt(a)); }
function locateNearestBranch(){
  const withCoords=branchList.filter(b=>{const info=BRANCH_INFO[b[0]];return info && info.lat!==null && info.lng!==null && Number(info.active??1)===1;});
  if(!withCoords.length){ toast(lang==='ar'?'لسه مفيش إحداثيات محفوظة للفروع — اختار فرعك يدويًا':"Branch locations aren't set up yet — please choose manually"); return; }
  if(!navigator.geolocation){ toast(lang==='ar'?'المتصفح لا يدعم تحديد الموقع':'Geolocation not supported'); return; }
  if(window.isSecureContext===false){ toast(lang==='ar'?'⚠️ تحديد الموقع بيشتغل بس لما الموقع يفتح بصيغة https — كلم مسؤول الموقع':'⚠️ Location only works when the site is loaded over https'); return; }
  const btn=document.getElementById('branchLocateBtn');
  const setBtn=(t)=>{ if(btn){btn.disabled=true;btn.textContent=t;} };
  const resetBtn=()=>{ if(btn){btn.disabled=false;btn.textContent=lang==='ar'?'📍 استخدم موقعي واقترح أقرب فرع':'📍 Use my location';} };
  const finish=(pos)=>{
    let best=null,bestDist=Infinity;
    withCoords.forEach(b=>{ const info=BRANCH_INFO[b[0]]; const dist=haversineKm(pos.coords.latitude,pos.coords.longitude,Number(info.lat),Number(info.lng)); if(dist<bestDist){bestDist=dist;best=b;} });
    resetBtn();
    if(best){ selectBranch(best[0]); toast((lang==='ar'?'✓ أقرب فرع ليك: ':'✓ Nearest branch: ')+branchName(best[0])+' (~'+bestDist.toFixed(1)+' كم)'); }
  };
  const fail=(err)=>{ resetBtn();
    const msg=err&&err.code===1?(lang==='ar'?'رفضت السماح بالوصول للموقع — فعّلها من إعدادات المتصفح وحاول تاني':'Location permission denied — enable it in browser settings and retry')
      :err&&err.code===3?(lang==='ar'?'الإشارة ضعيفة والموقع بياخد وقت طويل — جرّب في مكان مفتوح أو فعّل GPS':'Signal is weak and location is taking too long — try in an open area or enable GPS')
      :(lang==='ar'?'تعذر تحديد موقعك — تأكد إن خدمة الموقع (GPS) شغالة على جهازك':'Could not get your location — make sure GPS/location services are turned on');
    toast(msg); };
  setBtn(lang==='ar'?'📍 جاري تحديد موقعك...':'📍 Locating...');
  navigator.geolocation.getCurrentPosition(finish,(err1)=>{
    if(err1&&err1.code===1){ fail(err1); return; }
    setBtn(lang==='ar'?'📍 بيحاول بدقة أعلى...':'📍 Trying higher accuracy...');
    navigator.geolocation.getCurrentPosition(finish,fail,{enableHighAccuracy:true,timeout:15000,maximumAge:60000});
  },{enableHighAccuracy:false,timeout:5000,maximumAge:300000});
}
function effectiveHours(){
  const s=window.SG_SETTINGS||{}; const info=selectedBranch?BRANCH_INFO[selectedBranch]:null;
  const open=(info&&info.open_time)?info.open_time:(s.open_time||'12:00');
  const close=(info&&info.close_time)?info.close_time:(s.close_time||'00:00');
  return {open,close};
}
