function branchName(id){const b=branchList.find(x=>x[0]===id);return b?b[1]:'';}
function renderBranchChooser(){const box=document.getElementById('branchChooser');if(!box)return;box.innerHTML=`<div class="branch-chooser-title">📍 اختار الفرع الأقرب ليك <span>الأسعار والمنيو والتوافر بيختلفوا حسب الفرع — اختار مرة واحدة وهنفتكرلك اختيارك</span></div><button type="button" class="branch-locate-btn" id="branchLocateBtn" onclick="locateNearestBranch()">📍 استخدم موقعي واقترح أقرب فرع</button><div class="branch-grid">${branchList.map(b=>{const info=BRANCH_INFO[b[0]];const closed=info&&Number(info.active??1)===0;return `<button type="button" class="branch-option ${selectedBranch===b[0]?'selected':''} ${closed?'closed':''}" data-branch="${b[0]}" ${closed?'disabled':`onclick="selectBranch('${b[0]}')"`}><span>${b[1]}${closed?'<br><small>🔴 مغلق مؤقتًا</small>':''}</span><span class="branch-check">${selectedBranch===b[0]?'✓':''}</span></button>`;}).join('')}</div><div id="chosenBranchLine" class="chosen-branch-line" style="display:${selectedBranch?'block':'none'}">✓ فرعك المختار: <b>${branchName(selectedBranch)}</b></div>`;const closeBtn=document.getElementById('branchPickerClose');if(closeBtn)closeBtn.style.display=selectedBranch?'block':'none';}
