function selectBranch(id){const changed=selectedBranch!==id;selectedBranch=id||'';applyBranchUI();closeBranchPicker();if(changed&&Object.keys(cart).length){cart={};cartNotes={};cartMethods={};renderCart();}refreshBranchMenu();updateOpeningState();if(selectedBranch&&changed)toast((lang==='ar'?'✓ تم اختيار ':'✓ Selected ')+branchName(selectedBranch));}
