function toast(message){
  let el=document.getElementById('sgToast');
  if(!el){
    el=document.createElement('div'); el.id='sgToast';
    el.style.cssText='position:fixed;bottom:82px;left:50%;transform:translateX(-50%);z-index:200;background:#102d4f;color:#fff;padding:10px 16px;border-radius:999px;font-size:13px;font-weight:800;box-shadow:0 10px 30px #0003;max-width:90vw;text-align:center';
    document.body.appendChild(el);
  }
  el.textContent=message; el.style.display='block';
  clearTimeout(window.__sgToastTimer); window.__sgToastTimer=setTimeout(()=>{el.style.display='none'},2200);
}
