function renderCats(){
  const t = T[lang];
  const catKeys = Object.keys(MENU_DATA.cats);
  let html = `<button class="cat-btn ${activeCat==='ALL'?'active':''}" data-cat="ALL">${t.all}</button>`;
  html += catKeys.map(k => {
    const label = lang==='ar' ? MENU_DATA.cats[k][0] : MENU_DATA.cats[k][1];
    return `<button class="cat-btn ${activeCat===k?'active':''}" data-cat="${k}">${label}</button>`;
  }).join('');
  catsEl.innerHTML = html;
  catsEl.querySelectorAll('.cat-btn').forEach(b=>{
    b.onclick = ()=>{ activeCat = b.dataset.cat; renderCats(); renderMenu(); };
  });
}

function itemMode(item){
  const m=String(item?.pricing_mode||'qty');
  if(m==='weight' && item?.cat==='fish') return 'fish';
  if(m==='weight' && item?.cat==='shrimp') return 'shrimp';
  if(m==='weight') return 'weight';
  if(m==='plate') return 'plate';
  return 'qty';
}
function fmtWeight(grams){ return (Number(grams||0)/1000).toFixed(3); }
const MIN_WEIGHT_G=150, WEIGHT_STEP_G=50, DEFAULT_WEIGHT_G=500;
function normalizeWeight(g){g=Number(g)||0; return Math.max(MIN_WEIGHT_G,Math.round(g/WEIGHT_STEP_G)*WEIGHT_STEP_G);}
function isPresent(id){
  const v = cart[id];
  if(v===undefined) return false;
  if(typeof v==='object') return (v.count||0) > 0;
  return v > 0;
}
function methodFor(item){ const methods=item?.methods||[]; if(!methods.length)return null; const chosenId=cartMethods[item.id]; return methods.find(m=>m.id===chosenId) || methods[0]; }
function itemLinePrice(item, entry){
  const mode=itemMode(item);
  const method=methodFor(item); const extra=method?Number(method.extra_price||0):0;
  if(mode==='qty' || mode==='plate') return Math.round((Number(item.price||0)*Number(entry||0) + extra*Number(entry||0))*100)/100;
  const grams=normalizeWeight(entry?.weight||0);
  const qty=(mode==='fish') ? Math.max(1,Number(entry?.count||0)) : 1;
  return Math.round((Number(item.price||0)*grams/1000*qty + extra*qty)*100)/100;
}
function setItemMethod(id, methodId){ cartMethods[id]=methodId; renderMenu(); renderCart(); }
function methodSelectHtml(item){
  const methods=item.methods||[]; if(!methods.length) return '';
  const chosen=methodFor(item);
  const opts=methods.map(m=>{const label=(lang==='ar'?m.ar:(m.en||m.ar))+(Number(m.extra_price||0)>0?' (+'+Number(m.extra_price).toFixed(0)+(lang==='ar'?' ج.م':' EGP')+')':'');return `<option value="${m.id}" ${chosen&&chosen.id===m.id?'selected':''}>${label}</option>`;}).join('');
  return `<div class="method-select" style="margin:6px 0"><select onchange="setItemMethod('${item.id}', this.value)" style="width:100%;padding:9px;border-radius:10px;border:1px solid #ddd;font-size:12.5px">${opts}</select></div>`;
}

function renderMenu(){
  const t = T[lang];
  const q = searchQuery.trim().toLowerCase();
  let list = MENU_DATA.items.filter(it=>{
    if(activeCat!=='ALL' && it.cat!==activeCat) return false;
    if(q){
      const hay = (it.ar+' '+it.en).toLowerCase();
      if(!hay.includes(q)) return false;
    }
    return true;
  });

  if(list.length===0){
    menuEl.innerHTML = `<div class="no-results">${t.noResults}</div>`;
    return;
  }

  const groups = {};
  const order = [];
  list.forEach(it=>{
    if(!groups[it.cat]){ groups[it.cat]=[]; order.push(it.cat); }
    groups[it.cat].push(it);
  });

  menuEl.innerHTML = order.map(catKey=>{
    const label = lang==='ar' ? MENU_DATA.cats[catKey][0] : MENU_DATA.cats[catKey][1];
    const icon = MENU_DATA.icons[catKey] || '🍽️';
    const items = groups[catKey];
    const catNote = (catKey==='shrimp' || catKey==='fish') ? `<p class="menu-cat-note">${lang==='ar'?'⚖️ الوزن التقريبي يبدأ من 150 جم — يمكنك زيادته أو تقليله بالـ50 جم.':'⚖️ Approximate weight starts at 150g — adjust in 50g steps.'}</p>` : '';
    return `
    <h2 class="menu-cat-title">${icon} ${label}</h2>
    ${catNote}
    <div class="menu-grid">
      ${items.map(it=>{
        const mode = itemMode(it);
        const present = isPresent(it.id);
        const unavailable = it.available===false;
        const name = lang==='ar' ? it.ar : it.en;
        const desc = lang==='ar' ? it.dar : it.den;
        const cur = lang==='ar'?'ج.م':'EGP';

        let controlsHtml, totalHtml = '';

        if(unavailable){
          controlsHtml = `<div style=\"padding:10px 12px;border-radius:12px;background:#fff1f2;color:#b42318;font-weight:900;text-align:center\">🚫 ${lang==='ar'?'غير متاح حاليًا':'Currently unavailable'}</div>`;
        } else if(mode==='qty' || mode==='plate'){
          const amount = cart[it.id] || 0;
          const label = mode==='plate' ? (lang==='ar'?' طبق':' plate') : '';
          controlsHtml = amount>0
            ? `<div class="qty-stepper"><button onclick="changeQty('${it.id}',-1)">−</button><span>${amount}${label}</span><button onclick="changeQty('${it.id}',1)">+</button></div>`
            : `<button class="add-btn" onclick="changeQty('${it.id}',1)">+</button>`;
        } else if(mode==='fish') {
          const entry = cart[it.id] || {count:0,weight:0};
          if(entry.count>0){
            controlsHtml=`<div class="fish-controls">
              <div class="stepper-row"><span class="stepper-label">${lang==='ar'?'عدد السمك':'Fish count'}</span><div class="qty-stepper"><button onclick="changeWeightItemCount('${it.id}',-1)">−</button><span>${entry.count}</span><button onclick="changeWeightItemCount('${it.id}',1)">+</button></div></div>
              <div class="stepper-row" style="margin-top:6px"><span class="stepper-label">${lang==='ar'?'الوزن التقريبي':'Approx. weight'}</span><div class="qty-stepper weight"><button onclick="changeApproxWeight('${it.id}',-${WEIGHT_STEP_G})">−</button><span>${fmtWeight(entry.weight||DEFAULT_WEIGHT_G)} ${t.kgUnit}</span><button onclick="changeApproxWeight('${it.id}',${WEIGHT_STEP_G})">+</button></div></div>
              <div class="weight-total">${lang==='ar'?'وزن تقريبي لكل سمكة — الحد الأدنى 150 جم':'Approx. weight per fish — minimum 150g'}</div>
            </div>`;
          } else controlsHtml=`<button class="add-btn" onclick="addWeightedItem('${it.id}')">+</button>`;
        } else {
          const entry = cart[it.id] || {weight:0};
          if(entry.weight>0){
            controlsHtml=`<div class="fish-controls">
              <div class="stepper-row"><span class="stepper-label">${lang==='ar'?'الوزن التقريبي':'Approx. weight'}</span><div class="qty-stepper weight"><button onclick="changeApproxWeight('${it.id}',-${WEIGHT_STEP_G})">−</button><span>${fmtWeight(entry.weight||DEFAULT_WEIGHT_G)} ${t.kgUnit}</span><button onclick="changeApproxWeight('${it.id}',${WEIGHT_STEP_G})">+</button></div></div>
              <div class="weight-total">${lang==='ar'?(mode==='shrimp'?'الجمبري يُباع بالكيلو — الوزن التقريبي الكلي':'الوزن التقريبي الكلي'):(mode==='shrimp'?'Shrimp is sold by weight — total approximate weight':'Approximate total weight')}</div>
            </div>`;
          } else controlsHtml=`<button class="add-btn" onclick="addWeightedItem('${it.id}')">+</button>`;
        }
        return `
        <div class="item-card" style="${unavailable?'opacity:.72':''}">
          <div class="item-thumb">${icon}</div>
          <div class="item-info">
            <div class="item-name">${name}</div>
            ${desc ? `<div class="item-desc">${desc}</div>` : ''}
            ${it.serving_info ? `<div class="item-serving" style="font-size:11.5px;color:#6b7d78;margin-top:2px">⚖️ ${escTrack(it.serving_info)}</div>` : ''}
            ${it.ingredients_text ? `<div class="item-ingredients" style="font-size:11.5px;color:#6b7d78;margin-top:2px">🧾 ${lang==='ar'?'المكونات':'Ingredients'}: ${escTrack(it.ingredients_text)}</div>` : ''}
            ${(!unavailable && it.methods && it.methods.length) ? methodSelectHtml(it) : ''}
            <div class="item-footer">
              ${(['fish','shrimp','weight'].includes(mode)) ? '' : controlsHtml}
            </div>
            <div class="item-price-tag ${(['fish','shrimp','weight'].includes(mode))?'weight-price':''}">
              ${(['fish','shrimp','weight'].includes(mode))
                ? `⚖️ ${Number(it.price||0).toFixed(0)} ${cur} / ${lang==='ar'?'كجم':'kg'}`
                : `💰 ${Number(it.price||0).toFixed(0)} ${cur}`}
            </div>
            ${(['fish','shrimp','weight'].includes(mode)) ? controlsHtml : ''}
            ${present && !unavailable ? `<div class="note-field"><input type="text" placeholder="${t.notePlaceholder}" value="${(cartNotes[it.id]||'').replace(/"/g,'&quot;')}" oninput="updateNote('${it.id}', this.value)"></div>` : ''}
          </div>
        </div>`;
      }).join('')}
    </div>`;
  }).join('');
}

function getItem(id){ return MENU_DATA.items.find(it=>it.id===id); }

function changeQty(id, delta){
  cart[id] = (cart[id]||0) + delta;
  if(cart[id]<=0){ delete cart[id]; delete cartNotes[id]; }
  renderMenu();
  renderCart();
}

function changeWeight(id, delta){
  let g=Number(cart[id]||0); g=normalizeWeight(g===0?DEFAULT_WEIGHT_G:g+delta); cart[id]=g; renderMenu(); renderCart();
}
function addWeightedItem(id){ const item=getItem(id); cart[id]=(item&&item.cat==='fish')?{count:1,weight:DEFAULT_WEIGHT_G}:{weight:DEFAULT_WEIGHT_G}; renderMenu(); renderCart(); }
function changeWeightItemCount(id,delta){ const item=getItem(id); if(item&&item.cat==='shrimp') return; const e=cart[id]||{count:0,weight:DEFAULT_WEIGHT_G}; e.count=Number(e.count||0)+delta; if(e.count<=0){delete cart[id];delete cartNotes[id];} else {e.weight=normalizeWeight(e.weight||DEFAULT_WEIGHT_G);cart[id]=e;} renderMenu();renderCart(); }
function changeApproxWeight(id,delta){ const item=getItem(id); const e=cart[id]||((item&&item.cat==='shrimp')?{weight:DEFAULT_WEIGHT_G}:{count:1,weight:DEFAULT_WEIGHT_G}); e.weight=normalizeWeight(Number(e.weight||DEFAULT_WEIGHT_G)+delta); cart[id]=e; renderMenu();renderCart(); }
function updateFishWeight(id,value){ const e=cart[id]||{count:1,weight:DEFAULT_WEIGHT_G}; const m=String(value||'').replace(',','.').match(/[0-9]+(?:\.[0-9]+)?/); if(m){let g=Number(m[0]); if(/kg|كجم/i.test(value))g*=1000; e.weight=normalizeWeight(g); cart[id]=e; renderMenu();renderCart();} }

function updateNote(id, value){
  cartNotes[id] = value;
}

function cartSubtotal(){
  return Object.entries(cart).reduce((sum,[id,entry])=>{
    const item = getItem(id);
    const price = itemLinePrice(item, entry);
    return sum + (price===null ? 0 : price);
  },0);
}
function cartDiscount(){ return Math.round(cartSubtotal()*Number(window.SG_SETTINGS.discount||10)/100); }
function cartFinalTotal(){ return cartSubtotal() - cartDiscount(); }

function renderCart(){
  drawer.classList.remove('checkout-mode');
  drawerFoot.classList.remove('checkout-scroll');
  const t = T[lang];
  const entries = Object.entries(cart);
  cartCountEl.textContent = entries.length;

  if(entries.length===0){
    cartBody.innerHTML = `<div class="empty-cart">${t.emptyCart}</div>`;
    drawerFoot.innerHTML = `<button class="checkout-btn" disabled>${t.checkout}</button>`;
    return;
  }

  cartBody.innerHTML = entries.map(([id,entry])=>{
    const item = getItem(id);
    const mode = itemMode(item);
    const name = lang==='ar' ? item.ar : item.en;
    const icon = MENU_DATA.icons[item.cat] || '🍽️';
    const method = methodFor(item);
    const methodLine = method ? `<div class="cart-row-method" style="font-size:11.5px;color:#0f766e;margin-top:2px">🍳 ${lang==='ar'?method.ar:(method.en||method.ar)}${Number(method.extra_price||0)>0?' (+'+Number(method.extra_price).toFixed(0)+(lang==='ar'?' ج.م':' EGP')+')':''}</div>` : '';
    let qtyLine;
    if(mode==='qty') qtyLine = `${t.qtyLabel}: ${entry}`;
    else if(mode==='plate') qtyLine = `${lang==='ar'?'عدد الأطباق':'Plates'}: ${entry}`;
    else if(mode==='fish') qtyLine = `${lang==='ar'?'العدد':'Qty'}: ${entry.count} × ${lang==='ar'?'الوزن التقريبي لكل سمكة':'Approx. weight/fish'}: ${fmtWeight(entry.weight||DEFAULT_WEIGHT_G)} ${t.kgUnit}`;
    else qtyLine = `${lang==='ar'?'الوزن التقريبي':'Approx. weight'}: ${fmtWeight(entry.weight||DEFAULT_WEIGHT_G)} ${t.kgUnit}`;
    return `
    <div class="cart-row">
      <div class="item-thumb">${icon}</div>
      <div class="cart-row-info">
        <div class="cart-row-name">${name}</div>
        ${methodLine}
        <div class="cart-row-price">${qtyLine} · <strong>${itemLinePrice(item,entry).toFixed(0)} ${lang==='ar'?'ج.م':'EGP'}</strong></div>
        <div class="note-field">
          <input type="text" placeholder="${t.notePlaceholder}" value="${(cartNotes[id]||'').replace(/"/g,'&quot;')}" oninput="updateNote('${id}', this.value)">
        </div>
      </div>
      <button class="remove-btn" onclick="removeItem('${id}')">${t.remove}</button>
    </div>`;
  }).join('');

  drawerFoot.innerHTML = `
    <p class="checkout-note">💰 ${lang==='ar'?'الوزن بيتراجع عندنا، وهنأكد معاك السعر النهائي قبل التجهيز.':'We’ll check the available weight and confirm the final price with you before preparation.'}</p>
    <button class="checkout-btn" onclick="showCheckout()">${t.checkout}</button>
  `;
}

function removeItem(id){ delete cart[id]; delete cartNotes[id]; delete cartMethods[id]; renderMenu(); renderCart(); }

function buildOrderMessage(){
  const t = T[lang];
  const cur = lang==='ar'?'ج.م':'EGP';
  const lines = [];
  lines.push(t.waOrderTitle);
  lines.push('');
  Object.entries(cart).forEach(([id,entry])=>{
    const item = getItem(id);
    const mode = itemMode(item);
    const name = lang==='ar' ? item.ar : item.en;
    let line;
    if(mode==='qty') line = `• ${entry} × ${name}`;
    else if(mode==='plate') line = `• ${entry} طبق × ${name}`;
    else if(mode==='fish') line = `• ${name} — ${lang==='ar'?'العدد':'Qty'}: ${entry.count} — ${lang==='ar'?'الوزن التقريبي لكل سمكة':'Approx. weight/fish'}: ${fmtWeight(entry.weight)} ${t.kgUnit}`;
    else line = `• ${name} — ${lang==='ar'?'الوزن التقريبي':'Approx. weight'}: ${fmtWeight(entry.weight)} ${t.kgUnit}`;
    if(cartNotes[id] && cartNotes[id].trim()) line += `\n   (${cartNotes[id].trim()})`;
    lines.push(line);
  });
  lines.push('');
  lines.push('');
  lines.push(lang==='ar'?'💰 السعر النهائي يتم تأكيده مع العميل بعد مراجعة الأوزان وقبل تجهيز الطلب.':'💰 Final price is confirmed with the customer after weight review and before preparation.');
  return lines.join('\n');
}

function getWhatsAppLink(){
  const phone=(window.SG_SETTINGS?.whatsapp || '01021212601').replace(/\D/g,'');
  const intl=phone.startsWith('0') ? '20'+phone.slice(1) : phone;
  const lines=[lang==='ar'?'مرحبًا Sea Gull 👋':'Hello Sea Gull 👋','',lang==='ar'?'أريد التواصل مع المطعم والاستفسار عن الطلبات.':'I would like to contact the restaurant and ask about an order.'];
  return `https://wa.me/${intl}?text=${encodeURIComponent(lines.join('\n'))}`;
}

function showCheckout(){
  const t=T[lang]; deliveryLocation={lat:null,lng:null,accuracy:null}; drawer.classList.add('checkout-mode'); drawerFoot.classList.add('checkout-scroll');
  drawerFoot.innerHTML=`<div class="checkout-form">
    <h3>${lang==='ar'?'بيانات الطلب':'Order details'}</h3>
    <div class="checkout-branch-line">📍 <span id="inlineBranchName">${selectedBranch?branchName(selectedBranch):(lang==='ar'?'لم يتم اختيار فرع بعد':'No branch chosen yet')}</span><button type="button" class="branch-change-link" onclick="openBranchPicker()">${lang==='ar'?'تغيير الفرع':'Change branch'}</button></div>
    
    <input id="custName" type="text" placeholder="${lang==='ar'?'الاسم':'Name'}" required aria-required="true">
    <div id="custNameError" class="field-error" style="display:none"></div>
    <input id="custPhone" type="tel" placeholder="${lang==='ar'?'رقم الموبايل':'Mobile'}" required aria-required="true">
    <div id="custPhoneError" class="field-error" style="display:none"></div>
    <textarea id="custAddress" placeholder="${lang==='ar'?'العنوان بالتفصيل':'Full address'}" required aria-required="true"></textarea>
    <div id="custAddressError" class="field-error" style="display:none"></div>
    <div class="location-box"><button type="button" class="location-btn" id="locationBtn" onclick="captureLocation()">📍 ${lang==='ar'?'تحديد موقعي على الخريطة':'Share my delivery location'}</button><div id="locationStatus" class="location-status"><span class="gps-dot"></span>${lang==='ar'?'اختياري — يساعد الدليفري يوصل للمكان بدقة.':'Optional — helps the driver reach you accurately.'}</div><a id="locationLink" class="location-link" href="#" target="_blank" rel="noopener">${lang==='ar'?'فتح الموقع على الخريطة':'Open location on map'}</a><div class="location-help">${lang==='ar'?'اسم الشارع والعنوان يفضل أن يظل مكتوبًا حتى مع مشاركة اللوكيشن.':'Please keep the written address even when sharing the location.'}</div></div>
    <select id="paymentMethod" onchange="updatePaymentHelp()">${window.SG_SETTINGS.payment_cash!=='0'?`<option value="cash">${lang==='ar'?'كاش':'Cash'}</option>`:''}${window.SG_SETTINGS.payment_visa!=='0'?`<option value="visa">${lang==='ar'?'فيزا':'Visa'}</option>`:''}${window.SG_SETTINGS.payment_instapay!=='0'?`<option value="instapay">${lang==='ar'?'إنستا باي':'InstaPay'}</option>`:''}${window.SG_SETTINGS.payment_wallet!=='0'?`<option value="wallet">${lang==='ar'?'محفظة إلكترونية':'E-Wallet'}</option>`:''}</select><div id="paymentHelp" style="font-size:12px;color:#5C6D6A"></div>
    <textarea id="orderNote" placeholder="${lang==='ar'?'ملاحظات إضافية (اختياري)':'Additional notes (optional)'}"></textarea>
    <div id="checkoutError" class="checkout-error"></div>
    <button class="checkout-btn" onclick="submitOrder()">${lang==='ar'?'تأكيد الطلب':'Place order'}</button>
    <a class="back-link" href="#" onclick="renderCart();return false;">${t.back}</a>
  </div>`;
  updatePaymentHelp();
}
function clearCheckoutFieldError(id){const e=document.getElementById(id+'Error');if(e)e.style.display='none';const el=document.getElementById(id);if(el)el.style.borderColor='';}
function showCheckoutFieldError(id,msg){const e=document.getElementById(id+'Error');const el=document.getElementById(id);if(e){e.textContent=msg;e.style.display='block';}if(el)el.style.borderColor='#d92d20';}

function updatePaymentHelp(){
  const p=document.getElementById('paymentMethod')?.value, help=document.getElementById('paymentHelp');
  if(!help)return;
  if(p==='cash') help.textContent=lang==='ar'?'الدفع نقدًا عند الاستلام.':'Pay cash on delivery.';
  else if(p==='visa') help.textContent=(lang==='ar'?'الدفع بالفيزا عند الاستلام — ماكينة الدفع مع الدليفري':'Pay by Visa on delivery — the delivery driver carries the POS machine');
  else if(p==='instapay') help.textContent=(lang==='ar'?'الدفع عبر InstaPay — رقم التحويل: ':'Pay via InstaPay — transfer number: ')+(window.SG_SETTINGS.instapay||'01021212601');
  else help.textContent=(lang==='ar'?'الدفع عبر المحفظة الإلكترونية — رقم التحويل: ':'Pay via E-Wallet — transfer number: ')+(window.SG_SETTINGS.wallet_number||'01021212601');
}

function captureLocation(){
  const status=document.getElementById('locationStatus'),btn=document.getElementById('locationBtn'),link=document.getElementById('locationLink');
  if(!navigator.geolocation){status.textContent=lang==='ar'?'المتصفح لا يدعم تحديد الموقع.':'Geolocation is not supported by this browser.';return;}
  btn.disabled=true;btn.textContent=lang==='ar'?'📍 جاري تحديد موقعك...':'📍 Locating you...';
  navigator.geolocation.getCurrentPosition(pos=>{
    deliveryLocation={lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy};
    const br=BRANCH_INFO[selectedBranch]; if(br&&br.lat!=null&&br.lng!=null){const R=6371,rad=Math.PI/180,dLat=(deliveryLocation.lat-br.lat)*rad,dLng=(deliveryLocation.lng-br.lng)*rad,a=Math.sin(dLat/2)**2+Math.cos(br.lat*rad)*Math.cos(deliveryLocation.lat*rad)*Math.sin(dLng/2)**2,km=Math.round(R*2*Math.atan2(Math.sqrt(a),Math.sqrt(Math.max(0,1-a)))*10)/10,fee=Math.round(km*10*100)/100; const box=document.getElementById('locationStatus'); if(box)box.innerHTML=(lang==='ar'?'📍 المسافة التقريبية '+km.toFixed(1)+' كم — التوصيل '+fee.toFixed(2)+' ج.م':'📍 Approx. '+km.toFixed(1)+' km — delivery '+fee.toFixed(2)+' EGP');}
    const url=`https://www.google.com/maps?q=${deliveryLocation.lat},${deliveryLocation.lng}`;
    status.className='location-status ok';status.innerHTML=`✓ ${lang==='ar'?'تم تحديد موقعك بنجاح':'Location captured'}${pos.coords.accuracy?` — ±${Math.round(pos.coords.accuracy)}m`:''}`;
    link.href=url;link.classList.add('show');btn.disabled=false;btn.textContent=lang==='ar'?'📍 تم تحديد موقعي — اضغط للتحديث':'📍 Location selected — tap to update';
  },err=>{
    const msg=err.code===1?(lang==='ar'?'اسمح للموقع من إعدادات المتصفح ثم حاول مرة أخرى.':'Allow location access in your browser and try again.'): (lang==='ar'?'تعذر تحديد موقعك، جرّب مرة أخرى.':'Could not get your location. Please try again.');
    status.className='location-status';status.textContent=msg;btn.disabled=false;btn.textContent=lang==='ar'?'📍 تحديد موقعي على الخريطة':'Share my delivery location';
  },{enableHighAccuracy:true,timeout:12000,maximumAge:60000});
}

function buildCustomerOrderMessage(c){
  const t=T[lang]; const cur=lang==='ar'?'ج.م':'EGP';
  const lines=[t.waCustomerTitle,`${lang==='ar'?'رقم الطلب':'Order #'}: ${c.orderNo}`,'',`${lang==='ar'?'الاسم':'Name'}: ${c.name}`,`${lang==='ar'?'الموبايل':'Mobile'}: ${c.phone}`,`${lang==='ar'?'العنوان':'Address'}: ${c.address}`,`${lang==='ar'?'الدفع':'Payment'}: ${c.payment==='cash'?(lang==='ar'?'عند الاستلام':'Cash on delivery'):(lang==='ar'?'أونلاين':'Online')}`,''];
  Object.entries(cart).forEach(([id,entry])=>{ const item=getItem(id); if(!item)return; const mode=itemMode(item); const name=lang==='ar'?item.ar:item.en; let line=''; if(mode==='qty')line=`• ${entry} × ${name} — ${itemLinePrice(item,entry)} ${cur}`; else if(mode==='weight')line=`• ${name} — ${fmtWeight(entry)} ${t.kgUnit} — ${itemLinePrice(item,entry)} ${cur}`; else line=`• ${name} — ${t.countLabel}: ${entry.count} — ${t.weightLabel}: ${entry.weightNote||'-'}`; if(cartNotes[id]&&cartNotes[id].trim())line+=`\n   (${cartNotes[id].trim()})`; lines.push(line); });
  if(c.note)lines.push('',`${lang==='ar'?'ملاحظات':'Notes'}: ${c.note}`); lines.push('',`${t.total}: ${c.total} ${cur}`); return lines.join('\n');
}

async function submitOrder(){
  const name=document.getElementById('custName').value.trim();
  const phone=document.getElementById('custPhone').value.trim();
  const address=document.getElementById('custAddress').value.trim();
  const payment=document.getElementById('paymentMethod').value;
  const note=document.getElementById('orderNote').value.trim();
  const err=document.getElementById('checkoutError');
  const {open,close}=effectiveHours(); const now=new Date(), mins=now.getHours()*60+now.getMinutes(), op=open.split(':').map(Number), cl=close.split(':').map(Number), om=op[0]*60+op[1], cm0=cl[0]*60+cl[1], cm=cm0===0?1440:cm0; const isOpen=(om<=cm?mins>=om&&mins<cm:mins>=om||mins<cm);
  if(!isOpen){err.textContent=lang==='ar'?'المطعم مغلق حاليًا. مواعيد العمل من 12:00 ظهرًا حتى 12:00 منتصف الليل.':'The restaurant is currently closed. Opening hours are 12:00 PM to 12:00 AM.'; return;}
  clearCheckoutFieldError('custName'); clearCheckoutFieldError('custPhone'); clearCheckoutFieldError('custAddress');
  if(!selectedBranch){ openBranchPicker(); err.textContent=lang==='ar'?'برجاء اختيار الفرع أولاً':'Please choose your branch first'; return; }
  let firstInvalid=null;
  if(!name){ showCheckoutFieldError('custName',lang==='ar'?'اكتب اسمك':'Enter your name'); firstInvalid=document.getElementById('custName'); }
  if(!phone){ showCheckoutFieldError('custPhone',lang==='ar'?'اكتب رقم الموبايل':'Enter your mobile number'); if(!firstInvalid)firstInvalid=document.getElementById('custPhone'); }
  if(!address){ showCheckoutFieldError('custAddress',lang==='ar'?'اكتب العنوان بالتفصيل':'Enter your address'); if(!firstInvalid)firstInvalid=document.getElementById('custAddress'); }
  if(firstInvalid){ firstInvalid.focus(); err.textContent=lang==='ar'?'كمّل البيانات المطلوبة في نفس الصفحة':'Please complete the required details on this page'; return; }
  const items=Object.entries(cart).map(([id,entry])=>({id,entry,note:cartNotes[id]||'',method_id:cartMethods[id]||''}));
  if(!items.length){return;}
  const btn=document.querySelector('.checkout-form .checkout-btn'); btn.disabled=true; btn.textContent=lang==='ar'?'جاري إرسال الطلب...':'Submitting...';
  try{
    const receiptData='';
    const res=await fetch('api.php?action=create_order&_='+Date.now(),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,phone,address,payment,note,items,branch_id:selectedBranch,lat:deliveryLocation.lat,lng:deliveryLocation.lng,location_accuracy:deliveryLocation.accuracy,receipt_data:receiptData})});
    const data=await res.json();
    if(!data.ok) throw new Error(data.error||'Order failed');
    cart={}; cartNotes={}; cartMethods={}; renderMenu(); renderCart();
    const branchDone=branchList.find(b=>b[0]===selectedBranch);
    selectedBranch='';
    const needsReceipt=(payment==='instapay'||payment==='wallet');
    drawerFoot.innerHTML=`<div class="order-success" id="orderSuccessCard"><div class="success-icon">✓</div><h3>${lang==='ar'?'تم استلام طلبك ❤️':'Order received ❤️'}</h3><p>${lang==='ar'?'رقم الطلب':'Order #'} <b id="successOrderNo">${data.order_no}</b></p><button type="button" class="checkout-btn" style="margin-top:8px;background:#0f766e" onclick="copyOrderNumber('${data.order_no}')">📋 ${lang==='ar'?'نسخ رقم الطلب':'Copy order number'}</button><button type="button" class="checkout-btn" style="margin-top:8px;background:#102d4f" onclick="openTracking('${data.order_no}', '', '${data.access_token||''}')">🔎 ${lang==='ar'?'متابعة الطلب والسعر النهائي':'Track order & final price'}</button><button type="button" class="checkout-btn" style="margin-top:8px;background:#b42318" onclick="openTracking('${data.order_no}', '', '${data.access_token||''}', true)">🔐 ${lang==='ar'?'فتح رابط إلغاء الطلب':'Open private cancel link'}</button><p style="margin-top:12px;font-weight:800;color:#0f766e">📍 ${lang==='ar'?'طلبك متوجه إلى: '+(branchDone?branchDone[1]:'الفرع المختار'):'Your order is routed to: '+(branchDone?branchDone[1]:'selected branch')}</p><p>${lang==='ar'?'تم تسجيل طلبك بنجاح. هنراجع الوزن وهنأكد معاك السعر النهائي قبل التجهيز.':'Your order has been received. We’ll check the actual weight and confirm the final price with you before preparation.'}</p>${deliveryLocation.lat!==null?`<p style="color:#15803d">📍 ${lang==='ar'?'تم إرفاق موقع الاستلام بالطلب':'Delivery location attached'}</p>`:''}${needsReceipt?receiptUploadWidgetHtml(data.order_no, phone):''}<button class="checkout-btn" style="margin-top:10px;background:#102d4f" onclick="closeDrawer()">${lang==='ar'?'إغلاق':'Close'}</button></div>`;
  }catch(e){ const msg=String(e&&e.message||'').trim(); err.innerHTML=lang==='ar'?('⚠️ '+(msg||'تعذر إرسال الطلب حاليًا')+'<br><span style="font-size:12px">لو المشكلة استمرت، جرّب تحديث الصفحة.</span>'):('⚠️ '+(msg||'Unable to submit the order right now')+'<br><span style="font-size:12px">If the problem continues, refresh the page.</span>'); btn.disabled=false; btn.textContent=lang==='ar'?'تأكيد الطلب':'Place order'; }
}

async function openTracking(no, phone, token, cancel=false){const q='index.php?track='+encodeURIComponent(no)+(token?'&access_token='+encodeURIComponent(token):'&phone='+encodeURIComponent(phone||''))+(cancel?'&cancel=1':'');window.location.href=q;}

async function copyOrderNumber(no){
  try{await navigator.clipboard.writeText(String(no));toast(lang==='ar'?'✓ تم نسخ رقم الطلب':'✓ Order number copied');}
  catch(e){const ta=document.createElement('textarea');ta.value=String(no);document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();toast(lang==='ar'?'✓ تم نسخ رقم الطلب':'✓ Order number copied');}
}

function escTrack(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}

function receiptUploadWidgetHtml(orderNo, phone){
  const idSafe=String(orderNo).replace(/[^a-zA-Z0-9_-]/g,'');
  const orderSafe=String(orderNo).replace(/[^a-zA-Z0-9_-]/g,'');
  const phoneSafe=String(phone).replace(/\D/g,'');
  return `<div class="receipt-upload-box" id="ru_${idSafe}">
    <div style="font-weight:800;margin-bottom:6px">🧾 ${lang==='ar'?'ابعتلنا صورة إيصال التحويل':'Send us a photo of the payment receipt'}</div>
    <div style="font-size:12px;color:#687a76;margin-bottom:8px">${lang==='ar'?'اختياري بس بيسرّع تأكيد طلبك':'Optional, but it speeds up confirming your order'}</div>
    <input type="file" accept="image/*" id="rf_${idSafe}" style="width:100%;margin-bottom:8px">
    <button type="button" class="checkout-btn" style="background:#0f766e" onclick="uploadReceiptImage('${idSafe}','${orderSafe}','${phoneSafe}')">⬆️ ${lang==='ar'?'رفع الإيصال':'Upload receipt'}</button>
    <div id="ruMsg_${idSafe}" style="margin-top:8px;font-size:12.5px"></div>
  </div>`;
}

function fileToDataUrl(file){ return new Promise((resolve,reject)=>{ const r=new FileReader(); r.onload=()=>resolve(r.result); r.onerror=reject; r.readAsDataURL(file); }); }

async function uploadReceiptImage(idSafe, orderNo, phone){
  const input=document.getElementById('rf_'+idSafe); const msg=document.getElementById('ruMsg_'+idSafe);
  if(!input || !input.files || !input.files[0]){ if(msg)msg.innerHTML='<span style="color:#b42318">'+(lang==='ar'?'اختار صورة الإيصال الأول':'Choose the receipt image first')+'</span>'; return; }
  const file=input.files[0];
  if(file.size > 8*1024*1024){ if(msg)msg.innerHTML='<span style="color:#b42318">'+(lang==='ar'?'حجم الصورة كبير جدًا (الحد 8 ميجا)':'Image is too large (max 8MB)')+'</span>'; return; }
  try{
    const dataUrl=await fileToDataUrl(file);
    if(msg)msg.textContent=lang==='ar'?'جاري الرفع...':'Uploading...';
    const res=await fetch('api.php?action=upload_receipt',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({order_no:orderNo,phone:phone.replace(/\D/g,''),image_data:dataUrl})});
    const d=await res.json();
    if(!d.ok){ if(msg)msg.innerHTML='<span style="color:#b42318">'+escTrack(d.error||(lang==='ar'?'تعذر الرفع':'Upload failed'))+'</span>'; return; }
    if(msg)msg.innerHTML='<span style="color:#15803d;font-weight:800">✓ '+(lang==='ar'?'تم رفع الإيصال، شكرًا لك':'Receipt uploaded, thank you')+'</span>';
    toast(lang==='ar'?'✓ تم رفع إيصال الدفع':'✓ Payment receipt uploaded');
  }catch(e){ console.error(e); if(msg)msg.innerHTML='<span style="color:#b42318">'+(lang==='ar'?'تعذر الاتصال بالسيرفر':'Connection error')+'</span>'; }
}

function trackParams(){const u=new URL(window.location.href);return {no:u.searchParams.get('track')||'',ph:u.searchParams.get('phone')||'',token:u.searchParams.get('access_token')||''}}
function setTrackInputs(no,ph,token){const a=document.getElementById('trackNo'),b=document.getElementById('trackPhone'),c=document.getElementById('trackToken');if(a)a.value=no||'';if(b)b.value=ph||'';if(c)c.value=token||''}
async function trackOrder(silent=false){
  if(silent && document.getElementById('customerEditBox')?.style.display==='block') return;
  const no=document.getElementById('trackNo').value.trim();
  const ph=document.getElementById('trackPhone').value.trim();
  const token=(document.getElementById('trackToken')?.value||'').trim();
  const r=document.getElementById('trackResult');
  if(!no||(!ph&&!token)){ 
    r.innerHTML='<div style="color:#b42318;font-weight:700">'+(lang==='ar'?'من فضلك استخدم رابط الطلب أو اكتب رقم الطلب والموبايل':'Use your private order link or enter order number and phone')+'</div>';
    return;
  }
  try{
    const query=token?'&access_token='+encodeURIComponent(token):'&phone='+encodeURIComponent(ph.replace(/\D/g,''));
    const x=await fetch('api.php?action=track_order&order_no='+encodeURIComponent(no)+query,{cache:'no-store'});
    const d=await x.json();
    if(!d.ok){
      r.innerHTML='<div style="color:#b42318;font-weight:700">'+(lang==='ar'?'لم يتم العثور على الطلب':'Order not found')+'</div>';
      return;
    }
    const o=d.order||{}; window.__lastTrackedOrder=o;
    const names={
      new:lang==='ar'?'جديد':'New',
      accepted:lang==='ar'?'تم تأكيد السعر':'Price confirmed',
      preparing:lang==='ar'?'قيد التجهيز':'Preparing',
      ready:lang==='ar'?'جاهز':'Ready',
      out_for_delivery:lang==='ar'?'خرج للتوصيل':'Out for delivery',
      delivered:lang==='ar'?'تم التسليم':'Delivered',
      cancelled:lang==='ar'?'ملغي':'Cancelled'
    };
    const fmtWeight=g=>{
      const n=Number(g||0);
      return n>=1000?(n/1000).toFixed(3)+' كجم':Math.round(n)+' جم';
    };
    const itemRows=(Array.isArray(o.items)?o.items:[]).map(it=>{
      const mode=String(it.pricing_mode||'qty')==='weight';
      const actualW=(it.actual_weight!==null&&it.actual_weight!==undefined&&it.actual_weight!=='')?Number(it.actual_weight):Number(it.weight||0);
      const actualQ=(it.actual_qty!==null&&it.actual_qty!==undefined&&it.actual_qty!=='')?Number(it.actual_qty):Number(it.qty||0);
      const line=(it.actual_line_total!==null&&it.actual_line_total!==undefined&&it.actual_line_total!=='')?Number(it.actual_line_total):Number(it.line_total||0);
      const detail=mode
        ? '<div style="font-size:12px;color:#687a76;margin-top:4px">⚖️ '+(lang==='ar'?'الوزن النهائي':'Final weight')+': <b>'+fmtWeight(actualW)+'</b></div>'
        : '<div style="font-size:12px;color:#687a76;margin-top:4px">🔢 '+(lang==='ar'?'الكمية':'Quantity')+': <b>'+actualQ+'</b></div>';
      const methodDetail = it.method_name ? '<div style="font-size:12px;color:#0f766e;margin-top:2px">🍳 '+escTrack(it.method_name)+(Number(it.method_price||0)>0?' (+'+Number(it.method_price).toFixed(0)+' ج.م)':'')+'</div>' : '';
      return '<div style="padding:12px 0;border-bottom:1px solid #edf1ef;display:flex;justify-content:space-between;gap:12px;align-items:flex-start"><div><b>'+escTrack(it.item_name||'')+'</b>'+detail+methodDetail+'</div><strong style="white-space:nowrap">'+line.toFixed(2)+' ج.م</strong></div>';
    }).join('');

    let html='<div id="trackOrderCard" style="border:1px solid #dbe8e3;border-radius:18px;padding:16px;background:#fff">';
    html+='<div style="display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap"><b style="font-size:18px">#'+escTrack(o.order_no||no)+'</b><span style="padding:7px 11px;border-radius:999px;background:#e8f7ed;color:#15803d;font-weight:800">'+escTrack(names[o.status]||o.status||'')+'</span></div>';
    const branchNames={zayed:'فرع الشيخ زايد',dokki:'فرع الدقي',gleem:'فرع جليم',max:'فرع الماكس',marina:'فرع مارينا',madinaty:'فرع مدينتي',tagamoa:'فرع التجمع'};
    const shownBranch=branchNames[o.branch_id]||o.branch_id||'';
    html+='<div style="margin-top:12px;padding:10px 12px;border-radius:12px;background:#f7faf9;color:#35524d;font-size:12px">🏪 '+escTrack(shownBranch)+' &nbsp; • &nbsp; 📱 '+escTrack(ph)+'</div>';
    if(o.status==='cancelled'){
      html+='<div style="margin-top:14px;padding:15px;border-radius:14px;background:#fff5f1;border:1px solid #f0c9bd;color:#8b3d2a"><div style="font-weight:900;font-size:15px">'+(lang==='ar'?'نأسف لإلغاء طلبك ❤️':'We are sorry to see your order cancelled ❤️')+'</div><div style="margin-top:6px;line-height:1.7;font-size:13px">'+(lang==='ar'?'تم إلغاء الشيك الخاص بطلبك. نتمنى نشوفك مرة تانية، ويسعدنا جدًا نخدمك في طلبك القادم. 🙏':'Your order has been cancelled. We would be delighted to serve you again on your next order. 🙏')+'</div></div>';
    }else{
      const steps=[
        {k:'new',l:lang==='ar'?'جديد':'New'},
        {k:'accepted',l:lang==='ar'?'مؤكد':'Confirmed'},
        {k:'preparing',l:lang==='ar'?'التجهيز':'Preparing'},
        {k:'ready',l:lang==='ar'?'جاهز':'Ready'},
        {k:'out_for_delivery',l:lang==='ar'?'في الطريق':'On the way'},
        {k:'delivered',l:lang==='ar'?'تم التسليم':'Delivered'}
      ];
      const curIdx=steps.findIndex(s=>s.k===o.status); const idx=curIdx<0?0:curIdx;
      html+='<div class="order-progress">'+steps.map((s,i)=>{
        const cls=i<idx?'done':(i===idx?'current':'');
        const icon=i<idx?'✓':(i+1);
        return '<div class="step '+cls+'"><div class="dot">'+icon+'</div><div class="label">'+s.l+'</div></div>';
      }).join('')+'</div>';
    }
    html+='<div style="margin-top:16px"><b style="font-size:16px">'+(lang==='ar'?'🧾 تفاصيل الطلب':'🧾 Order details')+'</b><div style="margin-top:7px">'+(itemRows||'<div style="padding:12px;color:#7a8b86">'+(lang==='ar'?'لا توجد تفاصيل أصناف متاحة لهذا الطلب.':'No item details available for this order.')+'</div>')+'</div></div>';

    if(Number(o.price_pending)){
      html+='<div style="margin-top:14px;padding:12px;border-radius:12px;background:#fff7df;color:#8a5a00;font-weight:800">🟡 '+(lang==='ar'?'طلبك قيد المراجعة وسيتم إرسال السعر النهائي لك.':'Your order is being reviewed; the final price will be sent to you.')+'</div>';
    }else{
      html+='<div style="margin-top:16px"><b>'+(lang==='ar'?'تفاصيل السعر النهائي':'Final price details')+'</b></div>';
      html+='<div style="margin-top:9px;border-top:1px solid #eee">';
      html+='<div style="display:flex;justify-content:space-between;padding:9px 0"><span>'+(lang==='ar'?'إجمالي الأصناف':'Items subtotal')+'</span><b>'+Number(o.subtotal||0).toFixed(2)+' ج.م</b></div>';
      html+='<div style="display:flex;justify-content:space-between;padding:9px 0"><span>14%</span><b>'+Number(o.tax_amount||0).toFixed(2)+' ج.م</b></div>';
      html+='<div style="display:flex;justify-content:space-between;padding:9px 0"><span>'+(lang==='ar'?'التوصيل':'Delivery')+'</span><b>'+Number(o.delivery_fee||0).toFixed(2)+' ج.م</b></div>';
      html+='<div style="display:flex;justify-content:space-between;padding:9px 0"><span>'+(lang==='ar'?'الخصم':'Discount')+'</span><b>− '+Number(o.discount||0).toFixed(2)+' ج.م</b></div>';
      html+='</div>';
      html+='<div style="margin-top:8px;padding:14px;border-radius:14px;background:#f0fbf6;border:2px solid #1d9b68;display:flex;justify-content:space-between;align-items:center"><span style="font-weight:800">'+(lang==='ar'?'الإجمالي النهائي':'Final total')+'</span><strong style="font-size:22px;color:#087443">'+Number(o.total||0).toFixed(2)+' ج.م</strong></div>';
      if(Number(o.customer_confirmed)){
        html+='<div style="margin-top:12px;padding:13px;border-radius:12px;background:#e8f7ed;color:#15803d;font-weight:800">✅ '+(lang==='ar'?'تم تأكيد الطلب. هنبدأ التجهيز.':'Order confirmed. Preparation will start.')+'</div>';
      }else{
        html+='<div style="margin-top:14px;padding:13px;border-radius:12px;background:#fff8e7;color:#7a5200">'+(lang==='ar'?'راجع السعر النهائي ثم اضغط الزر بالأسفل لتأكيد الطلب وبدء التجهيز.':'Review the final price, then press the button below to confirm and start preparation.')+'</div>';
        html+='<button id="customerConfirmBtn" class="checkout-btn" style="margin-top:12px;background:#087a4f;font-size:16px;font-weight:900" onclick="confirmCustomerPrice()">✅ '+(lang==='ar'?'تأكيد الطلب وبدء التجهيز':'Confirm order & start preparation')+'</button>';
      }
    }
    if((o.payment==='instapay'||o.payment==='wallet') && !o.receipt_file){
      html+=receiptUploadWidgetHtml(o.order_no||no, ph);
    }else if((o.payment==='instapay'||o.payment==='wallet') && o.receipt_file){
      html+='<div style="margin-top:12px;padding:11px;border-radius:12px;background:#f0fbf6;color:#15803d;font-weight:700;font-size:12.5px">✓ '+(lang==='ar'?'تم استلام إيصال الدفع، شكرًا لك':'Payment receipt received, thank you')+'</div>';
    }
    const canCustomerChange=['new','accepted'].includes(String(o.status)) && !Number(o.cancel_requested);
    const privateLink=location.origin+'/index.php?track='+encodeURIComponent(o.order_no)+'&access_token='+encodeURIComponent(token);
    if(canCustomerChange){
      html+='<div style="margin-top:18px;padding:14px;border-radius:14px;background:#f8faf9;border:1px solid #dbe8e3">';
      html+='<b style="display:block;margin-bottom:8px">'+(lang==='ar'?'🛠️ محتاج تعدل الطلب؟':'🛠️ Need to change your order?')+'</b>';
      html+='<p style="margin:0 0 10px;color:#687a76;font-size:12px;line-height:1.6">'+(lang==='ar'?'تقدر تعدل الأصناف أو الكميات دلوقتي. أي تعديل هيرجع الطلب لمراجعة الوزن والسعر من جديد.':'You can change items or quantities now. Any change will return the order for price review.')+'</p>';
      html+='<button type="button" class="checkout-btn" style="background:#102d4f;margin-bottom:8px" onclick="showCustomerEdit()">✏️ '+(lang==='ar'?'تعديل الطلب':'Edit order')+'</button>';
      html+='<button type="button" class="checkout-btn" style="background:#b42318" onclick="customerCancelOrder()">✕ '+(lang==='ar'?'إلغاء الطلب الآن':'Cancel order')+'</button>';html+='<a href="'+privateLink+'&cancel=1" class="checkout-btn" style="display:block;text-align:center;margin-top:8px;background:#102d4f;text-decoration:none">🔐 '+(lang==='ar'?'رابط إلغاء الطلب الخاص':'Private cancellation link')+'</a>';
      html+='</div>';
    }else if(Number(o.cancel_requested)){
      html+='<div style="margin-top:16px;padding:13px;border-radius:12px;background:#fff7df;color:#8a5a00;font-weight:800">🟠 '+(lang==='ar'?'طلب الإلغاء قيد مراجعة المسؤول.':'Cancellation request is under manager review.')+'</div>';
    }
    html+='<div id="customerEditBox" style="display:none;margin-top:12px"></div>';
    html+='';
    html+='</div>';
    r.innerHTML=html;
    const confirmBtn=document.getElementById('customerConfirmBtn');
    if(confirmBtn){setTimeout(()=>confirmBtn.scrollIntoView({behavior:'smooth',block:'center'}),120);}
  }catch(e){
    console.error(e);
    r.innerHTML='<div style="color:#b42318;font-weight:700">'+(lang==='ar'?'تعذر الاتصال بالسيرفر':'Connection error')+'</div>';
  }
}

let trackTimer=null;function startTrackRealtime(){if(trackTimer)clearInterval(trackTimer);trackTimer=setInterval(()=>{if(document.getElementById('trackNo')?.value)trackOrder(true)},3000)}

startTrackRealtime();
async function confirmCustomerPrice(){const no=document.getElementById('trackNo').value.trim(),ph=document.getElementById('trackPhone').value.trim(),token=(document.getElementById('trackToken')?.value||'').trim(),r=document.getElementById('trackResult'),btn=document.getElementById('customerConfirmBtn');if(btn){btn.disabled=true;btn.textContent=lang==='ar'?'جاري التأكيد...':'Confirming...'}try{const x=await fetch('api.php?action=confirm_customer_price',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({order_no:no,phone:ph,access_token:token})});const d=await x.json();if(!d.ok){if(btn){btn.disabled=false;btn.textContent='✅ '+(lang==='ar'?'تأكيد الطلب وبدء التجهيز':'Confirm order & start preparation')}r.innerHTML='<div style="color:#b42318;font-weight:800">'+escTrack(d.error||'تعذر التأكيد')+'</div>';return}trackOrder()}catch(e){if(btn){btn.disabled=false}r.innerHTML='<div style="color:#b42318;font-weight:700">'+(lang==='ar'?'تعذر الاتصال بالسيرفر':'Connection error')+'</div>'}}

function showCustomerEdit(){
 const box=document.getElementById('customerEditBox');if(!box)return;
 const source=window.__lastTrackedOrder;if(!source||!Array.isArray(source.items))return;
 const existing=[...box.querySelectorAll('[data-customer-edit-item]')];if(existing.length){box.style.display='block';return;}
 box.style.display='block';
 const menuItems=Array.isArray(MENU_DATA?.items)?MENU_DATA.items:[];
 let html='<div style="padding:14px;border-radius:14px;background:#fff;border:1px solid #dbe8e3"><b>'+ (lang==='ar'?'تعديل الأصناف':'Edit items') +'</b>';
 source.items.forEach((it,i)=>{const mode=String(it.pricing_mode||'qty')==='weight';const q=it.actual_qty??it.qty??0;const w=it.actual_weight??it.weight??'';const amountTxt=mode?(Number(w||0)+' جم'):('الكمية: '+Number(q||0));html+='<div data-customer-edit-item="1" data-i="'+i+'" style="padding:12px 0;border-bottom:1px solid #edf1ef;display:flex;justify-content:space-between;align-items:center;gap:8px"><div><div style="font-weight:800">'+escTrack(it.item_name||'')+'</div><div style="color:#7a8a86;font-size:12px;margin-top:4px">'+amountTxt+(it.note?' — '+escTrack(it.note):'')+'</div></div><div style="font-size:11px;color:#9aa8a4">'+(lang==='ar'?'ثابت':'locked')+' 🔒</div></div>';});
 html+='<div style="color:#7a8a86;font-size:12px;margin-top:6px">'+(lang==='ar'?'الأصناف اللي اخترتها ثابتة، وممكن تضيف أصناف جديدة فقط من هنا 👇':'Items you already chose are locked — you can only add new items below 👇')+'</div>';
 html+='<div class="customer-edit-add"><b>➕ إضافة صنف جديد</b><div class="add-row"><select id="customerAddItem"><option value="">اختر صنفًا لإضافته</option>'+menuItems.map(it=>'<option value="'+escAttr(it.id)+'">'+escTrack(it.ar||it.en||it.id)+'</option>').join('')+'</select><button type="button" class="checkout-btn" style="margin:0;padding:10px 14px;background:#0f766e" onclick="addCustomerEditItem()">إضافة</button></div><div id="customerNewItems"></div></div>';
 html+='<button type="button" class="checkout-btn" style="margin-top:12px;background:#087a4f" onclick="saveCustomerEdit()">💾 '+(lang==='ar'?'حفظ التعديل وإعادة التسعير':'Save changes & reprice')+'</button><button type="button" class="checkout-btn" style="margin-top:8px;background:#777" onclick="document.getElementById(\'customerEditBox\').style.display=\'none\'">'+(lang==='ar'?'إغلاق':'Close')+'</button></div>';box.innerHTML=html;
}
function addCustomerEditItem(){const sel=document.getElementById('customerAddItem'),wrap=document.getElementById('customerNewItems');if(!sel||!wrap||!sel.value)return;const it=(MENU_DATA.items||[]).find(x=>String(x.id)===String(sel.value));if(!it)return;const idx=Date.now();const mode=String(it.pricing_mode||'qty')==='weight';const row=document.createElement('div');row.className='customer-edit-new';row.dataset.newItem='1';row.dataset.itemId=it.id;row.innerHTML='<div style="display:flex;justify-content:space-between;align-items:center;gap:8px"><b>'+escTrack(it.ar||it.en||it.id)+'</b><button type="button" class="remove" onclick="this.closest(\'.customer-edit-new\').remove()">حذف</button></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px">'+(mode?'<input data-new-weight type="number" min="150" step="50" placeholder="الوزن بالجرام">':'<input data-new-qty type="number" min="1" max="99" step="1" value="1" placeholder="الكمية">')+'<input data-new-note placeholder="ملاحظة"></div>';wrap.appendChild(row);sel.value='';}
function escAttr(v){return String(v??'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
async function saveCustomerEdit(){const no=document.getElementById('trackNo').value.trim(),token=(document.getElementById('trackToken')?.value||'').trim(),source=window.__lastTrackedOrder,box=document.getElementById('customerEditBox');if(!token||!source)return;const rows=[...box.querySelectorAll('[data-customer-edit-item]')];const items=rows.map((row)=>{const i=Number(row.dataset.i),it=source.items[i]||{};const q=it.actual_qty??it.qty??1;const w=it.actual_weight??it.weight??null;return {item_id:it.item_id,qty:Number(q)||1,weight:w!==null&&w!==''?Number(w):null,note:it.note||''}}).filter(x=>x.qty>0||x.weight>0);[...box.querySelectorAll('[data-new-item]')].forEach(row=>{const iid=row.dataset.itemId,q=row.querySelector('[data-new-qty]'),w=row.querySelector('[data-new-weight]'),n=row.querySelector('[data-new-note]');items.push({item_id:iid,qty:q?Number(q.value):1,weight:w?Number(w.value):null,note:n?n.value.trim():''});});try{const x=await fetch('api.php?action=customer_edit_order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({order_no:no,access_token:token,items})});const d=await x.json();if(!d.ok){toast(d.error||'تعذر تعديل الطلب');return}toast(lang==='ar'?'✓ تم تعديل الطلب وإضافة الأصناف وإرسال السعر للمراجعة من جديد':'✓ Order updated and new items added');trackOrder()}catch(e){toast(lang==='ar'?'تعذر الاتصال بالسيرفر':'Connection error')}}
async function customerCancelOrder(){const no=document.getElementById('trackNo').value.trim(),token=(document.getElementById('trackToken')?.value||'').trim();if(!token){toast(lang==='ar'?'استخدم رابط الطلب الخاص لإلغاء الطلب':'Use the private order link to cancel');return}const reason=prompt(lang==='ar'?'سبب إلغاء الطلب؟':'Why do you want to cancel?');if(!reason||reason.trim().length<3)return;try{const x=await fetch('api.php?action=customer_cancel_order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({order_no:no,access_token:token,reason:reason.trim()})});const d=await x.json();if(!d.ok){toast(d.error||'تعذر الإلغاء');return}toast(d.direct?(lang==='ar'?'✓ تم إلغاء الطلب':'✓ Order cancelled'):(lang==='ar'?'✓ تم إرسال طلب الإلغاء للمسؤول':'✓ Cancellation request sent to manager'));trackOrder()}catch(e){toast(lang==='ar'?'تعذر الاتصال بالسيرفر':'Connection error')}}

// Initial page bootstrap: render the menu immediately from the embedded menu data, then refresh public settings/menu from the server.
(function initCustomerPage(){ try { applyLangStrings(); renderCats(); renderMenu(); updateOpeningState(); applyBranchUI(); loadPublicBranches().then(()=>{ if(!selectedBranch && !new URLSearchParams(location.search).has('track')) setTimeout(openBranchPicker,180); }); if(selectedBranch){ refreshBranchMenu(); loadSiteSettings(); } else { applyBranchUI(); } } catch(e){console.error('Sea Gull page initialization failed:',e);} })();

(function(){const q=trackParams();if(q.no&&(q.ph||q.token)){setTrackInputs(q.no,q.ph,q.token);window.addEventListener('DOMContentLoaded',()=>{setTrackInputs(q.no,q.ph,q.token);trackOrder()})}})();
</script>
</body>
</html>
